//! One-shot generator for examples/hello/demo.png.
//!
//! The hello example references a small PNG via `#image(...)`. Rather
//! than committing the raw bytes generated by some out-of-tree tool,
//! this binary regenerates them from a deterministic pattern so the
//! `.png` in the repo is reproducible from the source on every host.
//!
//! Usage from the workspace root:
//!     `cargo run -p mos-eval --example gen_demo_png -- \
//!         examples/hello/demo.png`

#![allow(clippy::print_stderr, clippy::print_stdout, clippy::expect_used)]

use image::{Rgba, RgbaImage};

fn main() {
    let out = std::env::args()
        .nth(1)
        .expect("usage: gen_demo_png <output-path>");
    // 64×40 PNG: diagonal teal stripes with a darker border. Small
    // enough to keep the example repo lean, large enough that the
    // layout block visibly occupies space in the rendered PDF.
    let w = 64u32;
    let h = 40u32;
    let mut img = RgbaImage::new(w, h);
    for y in 0..h {
        for x in 0..w {
            let on_border = x < 2 || y < 2 || x >= w - 2 || y >= h - 2;
            let band = (x + y) / 6;
            let px = if on_border {
                Rgba([60, 80, 120, 255])
            } else if band % 2 == 0 {
                Rgba([180, 210, 230, 255])
            } else {
                Rgba([90, 140, 180, 255])
            };
            img.put_pixel(x, y, px);
        }
    }
    img.save(&out).expect("failed to write demo PNG");
    eprintln!("wrote {out}");
}
